import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.SyncWorldClocks{PayloadType: protocol.ClockPayloadTypeInitializeRegistry,
#   Clocks: []protocol.WorldClockData{{ID: 300, Name: "overworld", Time: -1, Paused: true,
#   TimeMarkers: []protocol.TimeMarkerData{{ID: 1, Name: "sunrise", Time: 23000,
#   Period: protocol.Option[int32](-24000)}, {ID: 2, Name: "noon", Time: 6000}}}}}
INITIALIZE_REGISTRY = bytes.fromhex(
    "0101ac02096f766572776f726c64010102010773756e72697365b0e7020140a2ffff02046e6f6f6ee05d00"
)

# generated by gophertunnel b8bd735:
# &packet.SyncWorldClocks{PayloadType: protocol.ClockPayloadTypeAddTimeMarker,
#   AddTimeMarkers: []protocol.TimeMarkerData{{Time: -1, Period: protocol.Option[int32](-1)}}}
ADD_TIME_MARKER = bytes.fromhex("02000100000101ffffffff")

# generated by gophertunnel b8bd735:
# &packet.SyncWorldClocks{PayloadType: protocol.ClockPayloadTypeRemoveTimeMarker,
#   RemoveClockID: 300, RemoveTimeMarkerIDs: []uint64{1, 200}}
REMOVE_TIME_MARKER = bytes.fromhex("03ac020201c801")

# generated by gophertunnel b8bd735:
# &packet.SyncWorldClocks{PayloadType: protocol.ClockPayloadTypeSyncState}
SYNC_STATE_EMPTY = bytes.fromhex("0000")

GOLDENS = [
    pytest.param(
        v2225.SyncWorldClocksPacket(
            data=v2225.SyncWorldClocksPacket.InitializeRegistryData(
                clock_data=[
                    v2225.WorldClockData(
                        id=300,
                        name="overworld",
                        time=-1,
                        is_paused=True,
                        time_markers=[
                            v2225.TimeMarkerData(id=1, name="sunrise", time=23000, period=-24000),
                            v2225.TimeMarkerData(id=2, name="noon", time=6000, period=None),
                        ],
                    )
                ]
            )
        ),
        INITIALIZE_REGISTRY,
        id="initialize-registry",
    ),
    pytest.param(
        v2225.SyncWorldClocksPacket(
            data=v2225.SyncWorldClocksPacket.AddTimeMarkerData(
                clock_id=0, time_markers=[v2225.TimeMarkerData(id=0, time=-1, period=-1)]
            )
        ),
        ADD_TIME_MARKER,
        id="add-time-marker",
    ),
    pytest.param(
        v2225.SyncWorldClocksPacket(
            data=v2225.SyncWorldClocksPacket.RemoveTimeMarkerData(clock_id=300, time_marker_ids=[1, 200])
        ),
        REMOVE_TIME_MARKER,
        id="remove-time-marker",
    ),
    pytest.param(
        v2225.SyncWorldClocksPacket(data=v2225.SyncWorldClocksPacket.SyncStateData()),
        SYNC_STATE_EMPTY,
        id="sync-state-empty",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_sync_world_clocks_is_packet_344(version):
    assert version.PACKETS[344] is version.SyncWorldClocksPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_sync_world_clocks_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_sync_world_clocks_decodes_from_its_golden(packet, golden):
    assert v2225.SyncWorldClocksPacket.from_bytes(golden) == packet
